<?php
// Extracts php-src's ext/standard/html_tables.h (itself generated by html_tables/html_table_gen.php) into the
// line-based resource Truffle PHP's builtins/HtmlTables.java loads. Run in the reference container, on the header
// of the PHP version the runtime follows:
//   tar -xJf /usr/src/php.tar.xz --strip-components=3 -C /tmp '*/ext/standard/html_tables.h'
//   php tools/html-tables.php /tmp/html_tables.h src/main/resources/pl/codeloom/php/builtins/html-tables.txt
// Output lines (numbers in hex):
//   charset <name> <index>            charset_map, index = enum entity_charset value
//   e2u <index> <cp>*256              enc_to_uni_index: a single-byte charset's code points (FFFF: unmapped)
//   u2e <table> <unicode>:<byte>...   unimap_<table>, sorted by code point
//   enc <table> <cp> <name>           stage-3 encode row: the entity for a code point
//   encm <table> <cp> <default|-> <second-cp>:<name>...   an ambiguous (two code point) stage-3 row
//   dec <table> <name> <cp1> <cp2>    the inverse (decode) hash tables, cp2 0 for one code point
$header = file_get_contents($argv[1]);
$out = [];

preg_match('/enum entity_charset \{(.*?)\};/s', $header, $m);
$charsets = array_map('trim', explode(',', preg_replace('/\/\*.*?\*\//s', '', $m[1])));
$charsetIndex = array_flip(array_values(array_filter($charsets)));
preg_match('/charset_map\[\] = \{(.*?)\n\};/s', $header, $m);
preg_match_all('/\{ "([^"]+)",\s+sizeof\("[^"]+"\)-1,\s+(cs_\w+) \}/', $m[1], $rows, PREG_SET_ORDER);
foreach ($rows as [, $name, $cs]) {
    $out[] = sprintf('charset %s %X', $name, $charsetIndex[$cs]);
}

preg_match_all('/static const enc_to_uni_stage2 (enc_to_uni_s2_\w+) = \{ \{(.*?)\} \};/s', $header, $rows, PREG_SET_ORDER);
$stage2 = [];
foreach ($rows as [, $name, $body]) {
    preg_match_all('/0x([0-9A-F]+)/', $body, $cps);
    $stage2[$name] = $cps[1];
}
preg_match_all('/static const enc_to_uni (enc_to_uni_\w+) = \{ \{(.*?)\}\s*\};/s', $header, $rows, PREG_SET_ORDER);
$stage1 = [];
foreach ($rows as [, $name, $body]) {
    preg_match_all('/&(enc_to_uni_s2_\w+)/', $body, $parts);
    $stage1[$name] = array_merge(...array_map(fn($p) => $stage2[$p], $parts[1]));
}
preg_match('/enc_to_uni_index\[cs_numelems\] = \{(.*?)\};/s', $header, $m);
foreach (array_map('trim', array_filter(array_map('trim', explode(',', $m[1])))) as $index => $entry) {
    if ($entry !== 'NULL') {
        $out[] = sprintf('e2u %X %s', $index, implode(' ', $stage1[substr($entry, 1)]));
    }
}

preg_match_all('/static const uni_to_enc unimap_(\w+)\[\] = \{(.*?)\n\};/s', $header, $rows, PREG_SET_ORDER);
foreach ($rows as [, $name, $body]) {
    preg_match_all('/\{ 0x([0-9A-F]+), 0x([0-9A-F]+) \}/', $body, $pairs, PREG_SET_ORDER);
    $out[] = "u2e $name " . implode(' ', array_map(fn($p) => "$p[1]:$p[2]", $pairs));
}

$multi = [];
preg_match_all('/static const entity_multicodepoint_row (multi_cp_\w+)\[\] = \{(.*?)\n\};/s', $header, $rows, PREG_SET_ORDER);
foreach ($rows as [, $name, $body]) {
    preg_match_all('/\{ \{(NULL|"\w+"),\s+(0x[0-9A-F]+|\d+),\s+\d+\} \}/', $body, $entries, PREG_SET_ORDER);
    $default = $entries[0][1] === 'NULL' ? '-' : trim($entries[0][1], '"');
    $seconds = [];
    foreach (array_slice($entries, 1) as [, $entity, $cp]) {
        $seconds[] = sprintf('%X:%s', hexdec($cp), trim($entity, '"'));
    }
    $multi[$name] = $default . ' ' . implode(' ', $seconds);
}
preg_match_all('/static const entity_stage3_row stage3_table_(\w+)_([0-9A-F]{5})\[\] = \{(.*?)\n\};/s', $header, $rows, PREG_SET_ORDER);
foreach ($rows as [, $table, $base, $body]) {
    preg_match_all('/\{0, \{ \{(NULL|"[^"]+"), \d+\} \} \}|\{1, \{ \{\(void \*\)(multi_cp_\w+), 0\} \} \}/', $body, $cells, PREG_SET_ORDER);
    if (count($cells) !== 64) {
        fwrite(STDERR, "stage3_table_{$table}_$base: " . count($cells) . " rows\n");
        exit(1);
    }
    foreach ($cells as $offset => $cell) {
        $cp = hexdec($base) + $offset;
        if (isset($cell[2])) {
            $out[] = sprintf('encm %s %X %s', $table, $cp, $multi[$cell[2]]);
        } elseif ($cell[1] !== 'NULL') {
            $out[] = sprintf('enc %s %X %s', $table, $cp, trim($cell[1], '"'));
        }
    }
}

preg_match_all('/static const entity_cp_map ht_bucket_(\w+)_[0-9A-F]+\[\] = \{(.*?)\};/', $header, $rows, PREG_SET_ORDER);
foreach ($rows as [, $table, $body]) {
    preg_match_all('/\{"([^"]+)", \d+, 0x([0-9A-F]+), (0x[0-9A-F]+|0)\}/', $body, $entries, PREG_SET_ORDER);
    foreach ($entries as [, $name, $cp1, $cp2]) {
        $out[] = sprintf('dec %s %s %X %X', $table, $name, hexdec($cp1), hexdec($cp2));
    }
}

file_put_contents($argv[2], implode("\n", $out) . "\n");
echo count($out), " lines\n";
